import { Platform, StyleSheet, Text as RNText, type TextProps } from "react-native"

export const fonts = {
  body: Platform.select({ web: "'Helvetica Neue', Helvetica, Arial, sans-serif", default: undefined }),
}
export const fontSizes = { body: 14, h1: 80 }
export const fontWeights = { body: "400", h1: "200" } as const
export const lineHeights = { body: 20 }
export const colors = { text: "#111111", background: "#f5f5f5", heading: "#b83f45" }

export function Text({ style, ...props }: TextProps) {
  return <RNText {...props} style={[styles.body, style]} />
}

const styles = StyleSheet.create({
  body: { fontFamily: fonts.body, fontSize: fontSizes.body, lineHeight: lineHeights.body, color: colors.text },
})

// Web: src/index.js mounts <App> with createRoot inside a HashRouter with one route "*".
// Mobile: Expo Router does this. app/_layout.tsx is the root and the todo-list screen is the route "/".
// Nothing else to port; screens can read the app routes from here.
export const APP_ROUTES = ["/"] as const

import { useState } from "react"
import { FlatList, Pressable, StyleSheet, Text, TextInput, View } from "react-native"

type Todo = { id: number; title: string; completed: boolean }

export default function TodoList() {
  const [todos, setTodos] = useState<Todo[]>([])
  const [title, setTitle] = useState("")
  const left = todos.filter((t) => !t.completed).length

  function add() {
    if (title.trim() === "") return
    setTodos([...todos, { id: Date.now(), title: title.trim(), completed: false }])
    setTitle("")
  }

  return (
    <View style={styles.page}>
      <div className="header">
        <Text role="heading" style={styles.title}>todos</Text>
      </div>
      <TextInput
        placeholder="What needs to be done?"
        value={title}
        onChangeText={setTitle}
        onSubmitEditing={add}
        style={styles.input}
      />
      <FlatList
        role="list"
        data={todos}
        keyExtractor={(t) => String(t.id)}
        renderItem={({ item }) => (
          <View role="listitem" style={styles.row}>
            <Pressable
              role="checkbox"
              aria-checked={item.completed}
              onPress={() => setTodos(todos.map((t) => (t.id === item.id ? { ...t, completed: !t.completed } : t)))}
            >
              <Text>{item.completed ? "☑" : "☐"}</Text>
            </Pressable>
            <Text style={styles.grow}>{item.title}</Text>
            <Pressable role="button" accessibilityLabel="Delete todo" onPress={() => setTodos(todos.filter((t) => t.id !== item.id))}>
              <Text>×</Text>
            </Pressable>
          </View>
        )}
      />
      {todos.length > 0 && (
        <View style={styles.row}>
          <Text style={styles.grow}>{left} {left === 1 ? "item" : "items"} left!</Text>
          <Pressable role="button" onPress={() => setTodos(todos.filter((t) => !t.completed))}>
            <Text>Clear completed</Text>
          </Pressable>
        </View>
      )}
    </View>
  )
}

const styles = StyleSheet.create({
  page: { flex: 1, padding: 16, gap: 12 },
  title: { fontSize: 48, textAlign: "center" },
  input: { borderWidth: 1, borderColor: "#ccc", padding: 12, fontSize: 18 },
  row: { flexDirection: "row", alignItems: "center", gap: 12, paddingVertical: 8 },
  grow: { flex: 1 },
})

import { useState } from "react"
import { FlatList, Pressable, StyleSheet, Text, TextInput, View } from "react-native"

type Todo = { id: number; title: string; completed: boolean }
type Filter = "all" | "active" | "completed"

export default function TodoList() {
  const [todos, setTodos] = useState<Todo[]>([])
  const [title, setTitle] = useState("")
  const [filter, setFilter] = useState<Filter>("all")
  const left = todos.filter((t) => !t.completed).length
  const completed = todos.length - left
  const allDone = todos.length > 0 && left === 0
  const shown = todos.filter((t) => (filter === "active" ? !t.completed : filter === "completed" ? t.completed : true))

  function add() {
    const value = title.trim()
    if (value === "") return
    setTodos([...todos, { id: Date.now(), title: value, completed: false }])
    setTitle("")
  }
  const toggle = (id: number) => setTodos(todos.map((t) => (t.id === id ? { ...t, completed: !t.completed } : t)))
  const toggleAll = () => setTodos(todos.map((t) => ({ ...t, completed: !allDone })))

  return (
    <View style={styles.page}>
      <Text role="heading" style={styles.title}>todos</Text>
      <TextInput
        accessibilityLabel="New Todo Input"
        placeholder="What needs to be done?"
        value={title}
        onChangeText={setTitle}
        onSubmitEditing={add}
        style={styles.input}
      />
      {todos.length > 0 && (
        <Pressable role="checkbox" aria-checked={allDone} accessibilityLabel="❯ Toggle All Input" onPress={toggleAll} style={styles.row}>
          <Text>{allDone ? "☑" : "☐"} Mark all as complete</Text>
        </Pressable>
      )}
      <FlatList
        role="list"
        data={shown}
        keyExtractor={(t) => String(t.id)}
        renderItem={({ item }) => (
          <View role="listitem" style={styles.row}>
            <Pressable role="checkbox" aria-checked={item.completed} onPress={() => toggle(item.id)}>
              <Text>{item.completed ? "☑" : "☐"}</Text>
            </Pressable>
            <Text style={[styles.grow, item.completed && styles.done]}>{item.title}</Text>
          </View>
        )}
      />
      {todos.length > 0 && (
        <View style={styles.footer}>
          <Text>{left} {left === 1 ? "item" : "items"} left!</Text>
          <View role="list" style={styles.row}>
            {(["all", "active", "completed"] as const).map((f) => (
              <View role="listitem" key={f}>
                <Pressable role="link" onPress={() => setFilter(f)}>
                  <Text style={filter === f ? styles.selected : undefined}>{f === "all" ? "All" : f === "active" ? "Active" : "Completed"}</Text>
                </Pressable>
              </View>
            ))}
          </View>
          {completed > 0 && (
            <Pressable role="button" onPress={() => setTodos(todos.filter((t) => !t.completed))}>
              <Text>Clear completed</Text>
            </Pressable>
          )}
        </View>
      )}
    </View>
  )
}

const styles = StyleSheet.create({
  page: { flex: 1, padding: 16, gap: 12 },
  title: { fontSize: 48, textAlign: "center" },
  input: { borderWidth: 1, borderColor: "#ccc", padding: 12, fontSize: 18 },
  row: { flexDirection: "row", alignItems: "center", gap: 12, paddingVertical: 8 },
  grow: { flex: 1 },
  done: { textDecorationLine: "line-through", color: "#999" },
  footer: { gap: 8 },
  selected: { fontWeight: "bold" },
})
